arguments.command:
python3 - <<'EOF' 2>&1 | head -50
import socket, ssl, urllib.request

# Test raw TCP connect to various hosts on 443/80
for host in ['github.com','raw.githubusercontent.com','cdn.jsdelivr.net','lightingtheword.com']:
    for port in [443, 80]:
        try:
            s = socket.create_connection((host, port), timeout=6)
            print("TCP OK", host, port)
            s.close()
        except Exception as e:
            print("TCP ERR", host, port, type(e).__name__, str(e)[:80])
EOF

